import { cards, mcqs } from "./helpers";

/**
 * Concept questions for Physics and Maths.
 *
 * The numerical practice in these subjects is generated by the solvers with
 * fresh numbers every time (src/lib/practice.ts); these cover the ideas a
 * formula engine cannot test — which law applies, what a unit means, which
 * statement is a misconception.
 */

export const PHYSICS_QUESTIONS = [
  ...mcqs("phys-motion", [
    { q: "Speed is a scalar. Velocity is…", choices: ["also a scalar", "speed in a stated direction", "the same as acceleration", "distance × time"], answer: "speed in a stated direction", why: "Velocity is a vector: it has a size (the speed) and a direction." },
    { q: "On a distance–time graph, the slope (gradient) gives…", choices: ["acceleration", "speed", "distance", "time"], answer: "speed", why: "Gradient = change in distance ÷ change in time, which is speed. On a velocity–time graph the gradient is acceleration." },
    { q: "On a velocity–time graph, the area under the line gives…", choices: ["acceleration", "displacement (distance travelled)", "force", "speed"], answer: "displacement (distance travelled)", why: "Area = velocity × time, which is distance." },
    { q: "A car's velocity falls from 20 m/s to 10 m/s. Its acceleration is…", choices: ["positive", "negative (it is decelerating)", "zero", "impossible to tell"], answer: "negative (it is decelerating)", why: "a = (v − u)/t is negative when v < u." },
  ]),
  ...mcqs("phys-force-laws", [
    { q: "Newton's first law says an object keeps moving at constant velocity unless…", choices: ["it runs out of energy", "a resultant force acts on it", "it is heavy", "it stops by itself"], answer: "a resultant force acts on it", why: "With no resultant force, velocity stays constant. Objects stop because of friction, which is a force." },
    { q: "1 newton is the force that gives…", choices: ["1 kg an acceleration of 1 m/s²", "1 g a speed of 1 m/s", "1 kg a weight of 1 N", "1 kg a speed of 1 m/s"], answer: "1 kg an acceleration of 1 m/s²", why: "From F = ma: 1 N = 1 kg × 1 m/s²." },
    { q: "When you push on a wall, the wall…", choices: ["does not push back", "pushes back on you with an equal force", "pushes back with a smaller force", "absorbs the force"], answer: "pushes back on you with an equal force", why: "Newton's third law: forces come in equal and opposite pairs acting on different objects." },
    { q: "Pressure increases when the same force acts on…", choices: ["a larger area", "a smaller area", "a heavier object", "a colder surface"], answer: "a smaller area", why: "P = F/A, so a smaller A gives a larger P. That is why a knife cuts and a wide tyre does not sink." },
  ]),
  ...mcqs("phys-gravitation", [
    { q: "On the Moon, an astronaut's mass is…", choices: ["less than on Earth", "the same as on Earth", "more than on Earth", "zero"], answer: "the same as on Earth", why: "Mass is the amount of matter and does not change. Weight (mg) is smaller because g is smaller." },
    { q: "Ignoring air resistance, a heavy ball and a light ball dropped together…", choices: ["the heavy one lands first", "the light one lands first", "land together", "it depends on their colour"], answer: "land together", why: "All objects fall with the same acceleration g when air resistance is negligible." },
    { q: "If the distance between two masses doubles, the gravitational force becomes…", choices: ["twice as big", "half as big", "a quarter as big", "unchanged"], answer: "a quarter as big", why: "F = Gm₁m₂/r²: doubling r divides F by 2² = 4." },
    { q: "Weight is measured in…", choices: ["kilograms", "newtons", "joules", "metres"], answer: "newtons", why: "Weight is a force (W = mg), so it is measured in newtons. Mass is in kilograms." },
  ]),
  ...mcqs("phys-work-energy", [
    { q: "You hold a heavy bag still for a minute. The work done on the bag is…", choices: ["large", "zero", "negative", "equal to its weight"], answer: "zero", why: "Work = force × distance moved in the direction of the force. The bag does not move, so no work is done on it (your muscles still use energy)." },
    { q: "Doubling an object's speed makes its kinetic energy…", choices: ["double", "four times as big", "half", "unchanged"], answer: "four times as big", why: "KE = ½mv²: doubling v multiplies KE by 2² = 4." },
    { q: "The principle of conservation of energy says energy…", choices: ["is used up", "can be created by machines", "is transferred, never created or destroyed", "only exists as heat"], answer: "is transferred, never created or destroyed", why: "Energy changes form (e.g. potential to kinetic) but the total stays the same." },
    { q: "1 watt is…", choices: ["1 joule per second", "1 newton per metre", "1 joule × 1 second", "1 volt per amp"], answer: "1 joule per second", why: "Power is the rate of energy transfer: P = E/t." },
  ]),
  ...mcqs("phys-heat", [
    { q: "Heat flows naturally from…", choices: ["cold to hot", "hot to cold", "large to small objects", "solids to gases only"], answer: "hot to cold", why: "Thermal energy moves from a higher temperature to a lower one until they are equal." },
    { q: "Heat reaches the Earth from the Sun mainly by…", choices: ["conduction", "convection", "radiation", "evaporation"], answer: "radiation", why: "Space is almost empty, so there is no material for conduction or convection. Radiation needs no medium." },
    { q: "While ice is melting, its temperature…", choices: ["rises steadily", "stays at 0 °C", "falls", "jumps to 100 °C"], answer: "stays at 0 °C", why: "The energy supplied breaks the bonds of the solid (latent heat) rather than raising the temperature." },
    { q: "Temperature and heat are…", choices: ["the same thing", "different: temperature is how hot, heat is energy transferred", "both measured in joules", "both measured in °C"], answer: "different: temperature is how hot, heat is energy transferred", why: "Temperature (°C or K) measures hotness; heat (J) is energy moving because of a temperature difference." },
  ]),
  ...mcqs("phys-light", [
    { q: "For reflection from a plane mirror…", choices: ["the angle of incidence equals the angle of reflection", "the angle of reflection is always 90°", "light bends towards the mirror", "the image is upside down"], answer: "the angle of incidence equals the angle of reflection", why: "Both angles are measured from the normal, and they are equal." },
    { q: "Light passing from air into glass…", choices: ["speeds up and bends away from the normal", "slows down and bends towards the normal", "does not change direction at any angle", "stops"], answer: "slows down and bends towards the normal", why: "Glass is optically denser, so light slows and bends towards the normal (unless it hits along the normal)." },
    { q: "The image in a plane mirror is…", choices: ["real and inverted", "virtual, upright and the same size", "smaller than the object", "behind the viewer"], answer: "virtual, upright and the same size", why: "It appears as far behind the mirror as the object is in front, and is laterally inverted (left–right reversed)." },
    { q: "The speed of light in a vacuum is about…", choices: ["340 m/s", "3 × 10⁸ m/s", "3 × 10⁵ m/s", "9.8 m/s"], answer: "3 × 10⁸ m/s", why: "About 300 000 km per second. 340 m/s is roughly the speed of sound in air." },
  ]),
  ...mcqs("phys-electricity", [
    { q: "An ammeter is connected…", choices: ["in parallel with the component", "in series with the component", "across the battery only", "anywhere, it does not matter"], answer: "in series with the component", why: "An ammeter measures the current flowing through, so the current must pass through it. A voltmeter goes in parallel." },
    { q: "In a series circuit, the current is…", choices: ["the same everywhere", "largest near the battery", "shared equally between components", "zero in the last component"], answer: "the same everywhere", why: "There is only one path, so the same current flows through every component." },
    { q: "Adding another resistor in parallel makes the total resistance…", choices: ["larger", "smaller", "unchanged", "zero"], answer: "smaller", why: "Each parallel branch is another path for current, so the total resistance falls." },
    { q: "A fuse protects a circuit by…", choices: ["storing charge", "melting and breaking the circuit if the current is too large", "increasing the voltage", "earthing the case"], answer: "melting and breaking the circuit if the current is too large", why: "The thin fuse wire heats and melts when the current exceeds its rating, cutting the supply." },
  ]),
];

export const MATHS_QUESTIONS = [
  ...mcqs("math-number-systems", [
    { q: "Which of these is irrational?", choices: ["0.75", "√2", "3/8", "√9"], answer: "√2", why: "√2 cannot be written as a fraction of whole numbers; its decimal never ends or repeats. √9 = 3." },
    { q: "Is 1 a prime number?", choices: ["Yes", "No"], answer: "No", why: "A prime has exactly two different factors, 1 and itself. 1 has only one factor." },
    { q: "Dividing by 1/4 is the same as…", choices: ["multiplying by 4", "dividing by 4", "multiplying by 1/4", "adding 4"], answer: "multiplying by 4", why: "Dividing by a fraction means multiplying by its reciprocal: how many quarters fit into a number is 4 times that number." },
  ]),
  ...mcqs("math-algebraic-expressions", [
    { q: "(a + b)² equals…", choices: ["a² + b²", "a² + 2ab + b²", "2a + 2b", "a² + ab + b²"], answer: "a² + 2ab + b²", why: "(a + b)(a + b) = a² + ab + ab + b². Forgetting the 2ab is the most common mistake." },
    { q: "Which are like terms?", choices: ["3x and 3y", "2x² and 5x²", "4x and 4x²", "7 and 7x"], answer: "2x² and 5x²", why: "Like terms have the same letters with the same powers; only the coefficients may differ." },
    { q: "a² − b² factorises as…", choices: ["(a − b)²", "(a − b)(a + b)", "(a + b)²", "a(a − b²)"], answer: "(a − b)(a + b)", why: "The difference of two squares: expanding (a − b)(a + b) gives a² − b²." },
  ]),
  ...mcqs("math-linear-equations", [
    { q: "To solve 3x + 5 = 20, the first step is usually to…", choices: ["divide by 5", "subtract 5 from both sides", "multiply by 3", "add 3x"], answer: "subtract 5 from both sides", why: "Undo the addition first, then the multiplication: 3x = 15, x = 5." },
    { q: "If the discriminant b² − 4ac of a quadratic is negative, it has…", choices: ["two real solutions", "one real solution", "no real solutions", "infinitely many solutions"], answer: "no real solutions", why: "The formula needs √(b² − 4ac), which has no real value when it is negative." },
    { q: "Two lines with the same gradient and different intercepts…", choices: ["meet at one point", "never meet", "are the same line", "meet at the origin"], answer: "never meet", why: "They are parallel, so the simultaneous equations have no solution." },
  ]),
  ...mcqs("math-ratio-percentage", [
    { q: "A price rises 10% and then falls 10%. Compared with the start it is…", choices: ["the same", "1% lower", "1% higher", "10% lower"], answer: "1% lower", why: "1.1 × 0.9 = 0.99: the fall is 10% of a larger amount." },
    { q: "Simple interest differs from compound interest because it…", choices: ["is paid only on the original amount", "is always larger", "is paid on the growing balance", "has no rate"], answer: "is paid only on the original amount", why: "Compound interest is calculated on the balance including earlier interest, so it grows faster." },
    { q: "In the ratio 2:3, the first part is what fraction of the whole?", choices: ["2/3", "2/5", "3/5", "1/2"], answer: "2/5", why: "There are 2 + 3 = 5 parts in total, of which the first takes 2." },
  ]),
  ...mcqs("math-geometry-triangles", [
    { q: "The angles of a triangle add up to…", choices: ["90°", "180°", "270°", "360°"], answer: "180°", why: "Always, for any triangle on a flat surface. A quadrilateral's add up to 360°." },
    { q: "Pythagoras' theorem applies to…", choices: ["every triangle", "right-angled triangles only", "equilateral triangles only", "circles"], answer: "right-angled triangles only", why: "c² = a² + b² holds only when the angle opposite c is 90°." },
    { q: "Which set of side lengths makes a right-angled triangle?", choices: ["2, 3, 4", "3, 4, 5", "4, 5, 6", "5, 6, 7"], answer: "3, 4, 5", why: "3² + 4² = 9 + 16 = 25 = 5²." },
  ]),
  ...mcqs("math-mensuration", [
    { q: "Area is measured in…", choices: ["cm", "cm²", "cm³", "litres"], answer: "cm²", why: "Area is two-dimensional, so square units. Volume is cm³; 1 litre = 1000 cm³." },
    { q: "Doubling the radius of a circle makes its area…", choices: ["double", "four times as big", "half", "π times as big"], answer: "four times as big", why: "A = πr²: doubling r multiplies the area by 2² = 4." },
    { q: "A cone's volume is what fraction of a cylinder with the same base and height?", choices: ["1/2", "1/3", "2/3", "the same"], answer: "1/3", why: "V(cone) = ⅓πr²h, one third of the cylinder's πr²h." },
  ]),
  ...mcqs("math-data-probability", [
    { q: "A probability must lie between…", choices: ["−1 and 1", "0 and 1", "0 and 100", "1 and 10"], answer: "0 and 1", why: "0 means impossible, 1 means certain. (As a percentage, 0% to 100%.)" },
    { q: "Which average is least affected by one very large value?", choices: ["Mean", "Median", "Range", "Total"], answer: "Median", why: "The median depends only on the middle position, so one extreme value barely moves it. The mean shifts towards it." },
    { q: "A fair coin lands heads 5 times in a row. The chance of heads next time is…", choices: ["less than 1/2", "1/2", "more than 1/2", "0"], answer: "1/2", why: "Each toss is independent; the coin has no memory." },
  ]),
];

